def overlaps(a: Path, b: Path) -> bool:
    def same(x: Path, y: Path) -> bool:
        try:
            return x == y or os.path.samefile(x, y)
        except OSError:
            return False
    return any(same(x, b) for x in (a, *a.parents)) or any(same(a, y) for y in (b, *b.parents))

