def close_idle_gui_bursts(self) -> None:
    idle = self.sandboxes.settings.gui_snapshot_idle
    now = time.monotonic()
    for sid in list(self._gui_burst):
        try:
            if self.sandboxes.get(sid)["status"] == "paused":
